// I18n.ts
import { unref } from 'vue';
import { createI18n } from 'vue-i18n';
import en from './locales/en.json';
import fr from './locales/fr.json';

export const i18n = createI18n({
  locale: 'en',
  fallbackLocale: 'en',
  messages: { en, fr },
});

/**
 * Normalize a locale string to a backend-friendly format (two-letter uppercase language code).
 * @param locale The locale string to normalize, e.g., "en-US", "fr-FR", "en", "fr".
 * @returns The normalized language code, e.g., "EN", "FR". Defaults to "EN" if the input is invalid or undefined.
 */
function normalizeLanguageCode(locale: string | undefined): string {
  const normalizedLanguageCode = locale
    ?.trim()
    .split(/[-_]/)[0]
    ?.slice(0, 2)
    .toUpperCase();

  return (normalizedLanguageCode != null) && normalizedLanguageCode.length > 0
    ? normalizedLanguageCode
    : 'EN';
}

/**
 * Read the active application language in the backend-friendly format.
 * @returns Two-letter uppercase language code like EN or FR.
 */
export function getActiveLanguageCode(): string {
  const locale = unref((i18n.global as { locale: unknown }).locale);
  return normalizeLanguageCode(typeof locale === 'string' ? locale : undefined);
}

