interface ApiClient {
  get<T>(url: string, config?: unknown): Promise<AxiosResponse<T>>
  post<T>(url: string, payload?: unknown, config?: unknown): Promise<AxiosResponse<T>>
  patch<T>(url: string, payload?: unknown, config?: unknown): Promise<AxiosResponse<T>>
  delete<T>(url: string, config?: Record<string, unknown>): Promise<AxiosResponse<T>>
}

interface ApiErrorPayload {
  message?: Array<string> | string
}

const axios: ApiClient = {
  get: async (url: string, config?: unknown) =>
    axiosLib.get(url, config as Record<string, unknown>),
  post: async (url: string, payload?: unknown, config?: unknown) =>
    axiosLib.post(url, payload, config as Record<string, unknown>),
  patch: async (url: string, payload?: unknown, config?: unknown) =>
    axiosLib.patch(url, payload, config as Record<string, unknown>),
  delete: async (url: string, config?: Record<string, unknown>) =>
    axiosLib.delete(url, config),
};

/**
 * Extract a readable error message from backend/API failures.
 * @param error Unknown error thrown by Axios or local code.
 * @returns Human-readable message when available.
 */
export function getApiErrorMessage(error: unknown): string | null {
  if (isAxiosError(error)) {
    const payload = error.response?.data as ApiErrorPayload | string | undefined;

    if (typeof payload === 'string' && payload.trim() !== '') {
      return payload;
    }

    const message = typeof payload === 'object' && payload !== null
      ? payload.message
      : undefined;
    if (typeof message === 'string' && message.trim() !== '') {
      return message;
    }

    if (Array.isArray(message)) {
      const firstMessage = message.find(
        (item): item is string => typeof item === 'string' && item.trim() !== '',
      );

      if (firstMessage !== undefined) {
        return firstMessage;
      }
    }
  }

  if (error instanceof Error && error.message.trim() !== '') {
    return error.message;
  }

  return null;
}

let propertyDataTypeOptionsCache: Array<PropertyDataTypeOptionDto> | null = null;
let propertyDataTypeOptionsPromise: Promise<Array<PropertyDataTypeOptionDto>> | null = null;

/**
 * Build authorization headers when token is available.
 * @returns Headers object with bearer token, or empty object.
 */
function authHeaders(): Record<string, string> {
  if (typeof token === 'string' && token.length > 0) {
    return { authorization: `Bearer ${token}` };
  }

  return {};
}

/**
 * Normalize a language code for backend requests, falling back to the active UI language.
 * @param languageCode Optional language code override.
 * @returns Two-letter uppercase language code.
 */
function resolveLanguageCode(languageCode?: string): string {
  const normalizedLanguageCode = languageCode
    ?.trim()
    .split(/[-_]/)[0]
    ?.slice(0, 2)
    .toUpperCase();

  if ((normalizedLanguageCode != null) && normalizedLanguageCode.length > 0) {
    return normalizedLanguageCode;
  }

  return getActiveLanguageCode();
}

/**
 * Normalize list payloads that may come as raw arrays or paginated envelopes.
 * @param payload Raw payload from backend.
 * @returns Normalized array.
 */
function extractArrayData<T>(
  payload: Array<T> | ApiArrayEnvelope<T> | undefined,
): Array<T> {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (payload !== undefined && Array.isArray(payload.items)) {
    return payload.items;
  }

  if (payload !== undefined && Array.isArray(payload.data)) {
    return payload.data;
  }

  return [];
}

/**
 * @returns A human-readable label for a property data type code.
 * @param code Property data type code.
 */
function formatPropertyDataTypeLabel(code: string): string {
  return code
    .toLowerCase()
    .split('_')
    .filter(Boolean)
    .map(part => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

/**
 * Load property data type options from the API.
 * @returns Array of PropertyDataTypeOptionDto.
 */
async function loadPropertyDataTypeOptions(): Promise<Array<PropertyDataTypeOptionDto>> {
  if (propertyDataTypeOptionsCache !== null) {
    return propertyDataTypeOptionsCache;
  }

  if (propertyDataTypeOptionsPromise !== null) {
    return propertyDataTypeOptionsPromise;
  }

  propertyDataTypeOptionsPromise = (async () => {
    const response: AxiosResponse<
      Array<PropertyDataTypeApi>
      | ApiArrayEnvelope<PropertyDataTypeApi>
      | undefined
    > = await axios.get(
      `${baseUrl}/isa95-material-model/property-data-type`,
      {
        headers: {
          ...authHeaders(),
          accept: '*/*',
        },
      },
    );

    const options = extractArrayData(response.data).map(item => ({
      code: item.code,
      id: item.id,
      label: formatPropertyDataTypeLabel(item.code),
    }));

    propertyDataTypeOptionsCache = options;
    propertyDataTypeOptionsPromise = null;
    return options;
  })();

  return propertyDataTypeOptionsPromise;
}

/**
 * @param options PropertyDataTypeOptionDto array to search within.
 * @param propertyDataTypeId Property data type ID to find.
 * @returns Matching PropertyDataTypeOptionDto or undefined.
 */
function getPropertyDataTypeOptionById(
  options: Array<PropertyDataTypeOptionDto>,
  propertyDataTypeId?: number,
): PropertyDataTypeOptionDto | undefined {
  return options.find(option => option.id === propertyDataTypeId);
}

/**
 * @param length length value from the form, expected to be a non-negative integer or empty.
 * @returns Parsed length as number or null.
 */
function parsePropertyLength(length: string): number | null {
  const normalizedLength = length.trim();

  if (normalizedLength === '' || normalizedLength === '-') {
    return null;
  }

  const parsedLength = Number(normalizedLength);
  if (!Number.isInteger(parsedLength) || parsedLength < 0) {
    throw new Error('Length must be a non-negative integer.');
  }

  return parsedLength;
}

/**
 * Parse a property default value from the form.
 * @param defaultValue Default value from the form, expected to be a string or empty.
 * @returns Parsed default value as string or null.
 */
function parsePropertyDefaultValue(defaultValue: string): string | null {
  const normalizedDefaultValue = defaultValue.trim();

  if (normalizedDefaultValue === '' || normalizedDefaultValue === '-') {
    return null;
  }

  return normalizedDefaultValue;
}

/**
 * Map API material class property to table row DTO.
 * @param property API material class property.
 * @param materialClassId Material class ID.
 * @param propertyDataTypeOptions Array of PropertyDataTypeOptionDto to resolve data type labels.
 * @returns MaterialClassPropertyRowDto.
 */
function mapMaterialClassPropertyToRow(
  property: MaterialClassPropertyApi,
  materialClassId: number,
  propertyDataTypeOptions: Array<PropertyDataTypeOptionDto>,
): MaterialClassPropertyRowDto {
  return {
    cardinality:
      property.propertySemanticsJson?.cardinality === 'array' ? 'array' : 'single',
    classId: materialClassId,
    code: property.code,
    dataType:
      getPropertyDataTypeOptionById(
        propertyDataTypeOptions,
        property.propertyDataTypeId,
      )?.label ?? '-',
    defaultValue: property.defaultValue ?? '',
    description: property.description ?? property.code,
    id: property.id,
    isCustom: property.isCustom,
    length: property.length === null || property.length === undefined
      ? '-'
      : String(property.length),
    propertyDataTypeId: property.propertyDataTypeId ?? 0,
  };
}

/**
 * Convert scalar values to displayable string.
 * @param value Input value.
 * @returns String representation or '-'.
 */
function scalarToString(value: unknown): string {
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }

  if (Array.isArray(value)) {
    return value.map(item => scalarToString(item)).join(', ');
  }

  if (value !== null && typeof value === 'object') {
    return JSON.stringify(value);
  }

  return '-';
}

/**
 * Format an API property key for display in the related materials panel.
 * @param key Raw API key.
 * @returns Human-readable label.
 */
function formatRelatedMaterialFieldLabel(
  key: string,
): string {
  const normalizedKey = Array.from(key).reduce<string>((result, character, index) => {
    const isUppercase = character >= 'A' && character <= 'Z';

    if (index > 0 && isUppercase) {
      return `${result}_${character}`;
    }

    return `${result}${character}`;
  }, '');

  return normalizedKey
    .split('_')
    .filter((part): part is string => part.length > 0)
    .map((part: string) => {
      if (part.length <= 2) {
        return part.toUpperCase();
      }

      return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    })
    .join('_');
}

/**
 * Build the display field list for a related material card.
 * @param item Related material payload from the API.
 * @param propertyValues Matched class-specific properties.
 * @returns Ordered list of fields to render.
 */
function buildRelatedMaterialFields(
  item: RelatedMaterialApi,
  propertyValues: Record<string, unknown> | undefined,
): Array<RelatedMaterialFieldDto> {
  const fields: Array<RelatedMaterialFieldDto> = [];

  if (typeof item.description === 'string' && item.description.trim() !== '') {
    fields.push({
      key: 'materialDescription',
      label: 'Material_Description',
      value: item.description,
    });
  }

  for (const [key, rawValue] of Object.entries(propertyValues ?? {})) {
    if (rawValue === null || rawValue === undefined) {
      continue;
    }

    const value = scalarToString(rawValue);
    if (value === '-') {
      continue;
    }

    fields.push({
      key,
      label: formatRelatedMaterialFieldLabel(key),
      value,
    });
  }

  return fields;
}

/**
 * Map related materials API payload to the dialog row DTO.
 * @param item Related material payload from the API.
 * @param materialClassId Selected material class identifier.
 * @returns Related material row for the UI.
 */
function mapRelatedMaterialToRow(
  item: RelatedMaterialApi,
  materialClassId: number,
): RelatedMaterialRowDto {
  const matchingProperty = item.properties?.find(
    property => property.materialClassId === materialClassId,
  );
  const propertyValues = matchingProperty?.propertiesJson;

  return {
    classId: matchingProperty?.materialClassId ?? materialClassId,
    fields: buildRelatedMaterialFields(item, propertyValues),
    materialCode: item.code,
  };
}

/**
 * Read a property value by key from ISA-95 material properties list.
 * @param properties Material properties array.
 * @param key Property key to resolve.
 * @returns Resolved value as string or '-'.
 */
function getPropertyValue(
  properties: Array<MaterialDefinitionPropertyApi> | undefined,
  key: string,
): string {
  if (properties === undefined) {
    return '-';
  }

  for (const property of properties) {
    const values = property.values;
    if (values === undefined) {
      continue;
    }

    const matchedEntry = Object.entries(values).find(([propertyKey]) => propertyKey === key);
    if (matchedEntry === undefined) {
      continue;
    }

    const [, value] = matchedEntry;
    if (value === null || value === undefined) {
      continue;
    }

    return scalarToString(value);
  }

  return '-';
}

/**
 * Resolve the material type displayed in the UI.
 * Uses special stock type only.
 * @param item API material definition.
 * @returns Display value for type column/field.
 */
function getMaterialType(item: MaterialDefinitionApi): string {
  const directSpecialStockType = item.specialStockType?.trim();
  if (typeof directSpecialStockType === 'string' && directSpecialStockType !== '') {
    return directSpecialStockType;
  }

  const propertyBasedSpecialStockType = [
    getPropertyValue(item.properties, 'specialStockType'),
    getPropertyValue(item.properties, 'SpecialStockType'),
    getPropertyValue(item.properties, 'Special_Stock_Type'),
  ].find(value => value !== '-');

  if (typeof propertyBasedSpecialStockType === 'string' && propertyBasedSpecialStockType !== '') {
    return propertyBasedSpecialStockType;
  }

  return '-';
}

/**
 * Map API material definition to table row DTO.
 * @param item API material definition.
 * @returns Material row DTO.
 */
function mapMaterialDefinitionToRow(item: MaterialDefinitionApi): MaterialRowDto {
  return {
    description: item.description ?? '-',
    materialClasses: (item.materialClasses ?? []).map(materialClass => (
      materialClass.description ?? materialClass.code
    )),
    materialCode: item.code,
    storageLocations: item.storageLocations ?? [],
    type: getMaterialType(item),
  };
}

/**
 * Extract all key-value pairs from the physical property class.
 * @param properties Material properties array from the API.
 * @returns Ordered list of label/value entries.
 */
function extractPhysicalProperties(
  properties: Array<MaterialDefinitionPropertyApi> | undefined,
): Array<PhysicalPropertyEntryDto> {
  const physProperty = properties?.find(p => p.classCode === 'physicalProperty');

  if (physProperty?.valueDescriptions === undefined) {
    return [];
  }

  const valuesEntries = new Map(Object.entries(physProperty.values ?? {}));

  return Object.entries(physProperty.valueDescriptions).map(([key, label]) => {
    const raw: unknown = valuesEntries.get(key);
    let value: string;

    if (Array.isArray(raw)) {
      value = (raw as Array<unknown>).map(String).join(', ');
    }
    else if (raw === null || raw === undefined) {
      value = '-';
    }
    else if (typeof raw === 'object') {
      value = JSON.stringify(raw);
    }
    else {
      value = String(raw as string | number | boolean);
    }

    return { label, value };
  });
}

/**
 * Map class assignments from the API to the detail dialog model.
 * @param item API material definition.
 * @returns Class assignments for the editor.
 */
function extractMaterialClassAssignments(
  item: MaterialDefinitionApi,
): Array<MaterialClassAssignmentDto> {
  return (item.materialClasses ?? []).map(materialClass => ({
    code: materialClass.code,
    description: materialClass.description ?? materialClass.code,
    id: materialClass.id,
  }));
}

/**
 * Map property payloads from the API to class-based groups for the editor.
 * @param item API material definition.
 * @returns Property groups keyed by class.
 */
function extractMaterialPropertyGroups(
  item: MaterialDefinitionApi,
): Array<MaterialPropertyGroupDto> {
  return (item.properties ?? []).map(property => ({
    classCode: property.classCode ?? `Class ${property.materialClassId}`,
    classDescription:
      property.classDescription
      ?? property.classCode
      ?? `Class ${property.materialClassId}`,
    classId: property.materialClassId,
    values: { ...property.values },
  }));
}

/**
 * Map API material definition to detail dialog DTO.
 * @param item API material definition.
 * @returns Material details DTO.
 */
function mapMaterialDefinitionToDetails(item: MaterialDefinitionApi): MaterialDetailsDto {
  const classAssignments = extractMaterialClassAssignments(item);

  return {
    classAssignments,
    classes: classAssignments.map(materialClass => materialClass.description),
    description: item.description ?? '-',
    id: item.id,
    materialCode: item.code,
    physicalProperties: extractPhysicalProperties(item.properties),
    propertyGroups: extractMaterialPropertyGroups(item),
    specialProcurement: getPropertyValue(item.properties, 'Special_Procurement'),
    storageLocations: item.storageLocations ?? [],
    type: getMaterialType(item),
  };
}

interface FetchMaterialDefinitionsResult {
  items: Array<MaterialDefinitionApi>
  total: number
}

/**
 * Fetch material definitions from master API.
 * @param plant Plant identifier.
 * @param search Material code search term.
 * @param page Page number (1-based).
 * @param limit Number of items per page.
 * @returns Material definition items and total count.
 */
async function fetchMaterialDefinitions(
  plant: number,
  search?: string,
  page = 1,
  limit = 100,
): Promise<FetchMaterialDefinitionsResult> {
  const normalizedSearch = typeof search === 'string' ? search.trim() : '';
  const parameters: Record<string, number | string> = {
    languageCode: resolveLanguageCode(),
    limit,
    page,
    plant,
  };

  if (normalizedSearch !== '') {
    parameters.code = normalizedSearch;
  }

  const response: AxiosResponse<
    Array<MaterialDefinitionApi>
    | ApiArrayEnvelope<MaterialDefinitionApi>
    | undefined
  > = await axios.get(
    `${baseUrl}${MATERIAL_DEFINITION_PATH}`,
    {
      headers: authHeaders(),
      params: parameters,
    },
  );

  const items = extractArrayData(response.data);
  const envelope = response.data as ApiArrayEnvelope<MaterialDefinitionApi> | undefined;
  const total = typeof envelope?.total === 'number' ? envelope.total : items.length;

  return { items, total };
}

/**
 * Fetch material definitions mapped to the material table rows.
 * @param plant Plant identifier.
 * @param search Search text from the material field.
 * @returns Material list filtered by backend using code criteria.
 */
export async function getMaterials(plant: number, search?: string): Promise<Array<MaterialRowDto>> {
  const { items } = await fetchMaterialDefinitions(plant, search);
  return items.map(item => mapMaterialDefinitionToRow(item));
}

