}

interface ApiClient {
  get<T>(url: string, config?: unknown): Promise<AxiosResponse<T>>
}

const axios: ApiClient = {
  get: async (url: string, config?: unknown) =>
    axiosLib.get(url, config as Record<string, unknown>),
};

/**
 * Build authorization headers when token is available.
 * @returns Headers object with bearer token, or empty object.
 */
function authHeaders(): Record<string, string> {
  if (typeof token === 'string' && token.length > 0) {
    return { authorization: `Bearer ${token}` };
  }

  return {};
}

/**
 * Normalize list payloads that may come as raw arrays or paginated envelopes.
 * @param payload Raw payload from backend.
 * @returns Normalized array.
 */
function extractArrayData<T>(
  payload: Array<T> | ApiArrayEnvelope<T> | undefined,
): Array<T> {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (payload !== undefined && Array.isArray(payload.items)) {
    return payload.items;
  }

  if (payload !== undefined && Array.isArray(payload.data)) {
    return payload.data;
  }

  return [];
}

/**
 * Map an operation definition API response to a row DTO.
 * @param item Raw operation definition from API.
 * @returns OperationDefinitionRowDto mapped from raw item.
 */
function mapToRow(item: OperationDefinitionApi): OperationDefinitionRowDto {
  return {
    operationId: item.operationId ?? item.operationDefinitionId ?? '',
    material: item.material ?? item.materialCode ?? '',
    equipment: item.equipment ?? item.equipmentName ?? '',
    effectiveStartDate: item.effectiveStartDate ?? item.effectiveStartTimestamp ?? '',
    effectiveEndDate: item.effectiveEndDate ?? item.effectiveEndTimestamp ?? '',
  };
}

/**
 * Fetch a paginated list of operation definitions.
 * @param page 1-based page number.
 * @param limit Rows per page.
 * @param equipment Optional equipment filter value.
 * @param material Optional material filter value.
 * @returns Paginated result with rows and total count.
 */
export async function getOperationDefinitionsPage(
  page: number,
  limit: number,
  equipment?: string,
  material?: string,
): Promise<{ rows: Array<OperationDefinitionRowDto>, total: number }> {
  const parameters: Record<string, string | number> = {
    page,
    limit,
  };

  if (equipment !== undefined && equipment !== '') {
    parameters.equipment = equipment;
  }

  if (material !== undefined && material !== '') {
    parameters.material = material;
  }

  const response: AxiosResponse<
    Array<OperationDefinitionApi> | ApiArrayEnvelope<OperationDefinitionApi> | undefined
  > = await axios.get(`${baseUrl}${OPERATION_DEFINITION_PATH}`, {
    headers: { ...authHeaders(), accept: '*/*' },
    params: parameters,
  });

  const envelope = response.data;
  const items = extractArrayData(envelope);
  const total
    = Array.isArray(envelope) || envelope === undefined
      ? items.length
      : (envelope.total ?? items.length);

  return {
    rows: items.map(item => mapToRow(item)),
    total,
  };
}

/**
 * Fetch the list of available equipment for the filter dropdown.
 * @returns Array of EquipmentOptionDto.
 */
export async function getEquipmentOptions(): Promise<Array<EquipmentOptionDto>> {
  const response: AxiosResponse<
    Array<EquipmentApi> | ApiArrayEnvelope<EquipmentApi> | undefined
  > = await axios.get(`${baseUrl}${EQUIPMENT_PATH}`, {
    headers: { ...authHeaders(), accept: '*/*' },
  });

  return extractArrayData(response.data).map(item => ({
    id: item.id,
    label: item.name ?? item.code ?? item.id,
  }));
}

/**
 * Fetch the list of available materials for the filter dropdown.
 * @returns Array of MaterialOptionDto.
 */
export async function getMaterialOptions(): Promise<Array<MaterialOptionDto>> {
  const response: AxiosResponse<
    Array<MaterialApi> | ApiArrayEnvelope<MaterialApi> | undefined
  > = await axios.get(`${baseUrl}${MATERIAL_PATH}`, {
    headers: { ...authHeaders(), accept: '*/*' },
  });

  return extractArrayData(response.data).map(item => ({
    id: item.id,
    label: item.name ?? item.code ?? item.id,
  }));
}

