  const currentPage = ref(1);
  const selectedEquipment = ref<string | undefined>(undefined);
  const selectedMaterial = ref<string | undefined>(undefined);
  const equipmentOptions = ref<Array<EquipmentOptionDto>>([]);
  const materialOptions = ref<Array<MaterialOptionDto>>([]);

  /**
   * Load a page of operation definition rows from the API or mock data.
   * @param page 1-based page number to load.
   */
  async function loadRows(page = currentPage.value): Promise<void> {
    if (USE_MOCK) {
      rows.value = MOCK_ROWS;
      totalRows.value = 49;
      currentPage.value = page;
      return;
    }

    const result = await getOperationDefinitionsPage(
      page,
      ROWS_PER_PAGE,
      selectedEquipment.value,
      selectedMaterial.value,
    );
    rows.value = result.rows;
    totalRows.value = result.total;
    currentPage.value = page;
  }

  /**
   * Load equipment and material options for the filter dropdowns.
   */
  async function loadFilterOptions(): Promise<void> {
    if (USE_MOCK) {
      equipmentOptions.value = [
        { id: 'ARM-X500', label: 'Auto Assembly Robot ARM-X500' },
        { id: 'CAM-901', label: 'High-Res Inspection Camera CAM-901' },
        { id: 'RW-2500', label: 'Robotic Welder RW-2500' },
        { id: 'IF-4000', label: 'Industrial Furnace IF-4000' },
        { id: 'UC-600', label: 'Ultrasonic Cleaner UC-600' },
      ];
      materialOptions.value = [
        { id: 'MAT-45679-B', label: 'MAT-45679-B' },
      ];
      return;
    }

    const [equipment, materials] = await Promise.all([
      getEquipmentOptions(),
      getMaterialOptions(),
    ]);
    equipmentOptions.value = equipment;
    materialOptions.value = materials;
  }

  /**
   * Reset all filters and go back to the first page.
   */
  function resetFilters(): void {
    selectedEquipment.value = undefined;
    selectedMaterial.value = undefined;
    currentPage.value = 1;
  }

  return {
    currentPage,
    equipmentOptions,
    materialOptions,
    rows,
    selectedEquipment,
    selectedMaterial,
    totalRows,
    loadFilterOptions,
    loadRows,
    resetFilters,
  };
});

